R=pathlib.Path(__file__).resolve().parents[1];m=runpy.run_path(str(R/'automation/draw-space-frequency-similarity.py'));np=m['np'];a=m['compute']([['室','室','门'],['室','门','门']]);np.testing.assert_allclose(a[0,1],.8);d=json.load(open(R/'reports/chapter-space-raw-frequency-similarity.json',encoding='utf8'));a=np.array(d['similarity'],dtype=float);assert a.shape==(491,491);np.testing.assert_allclose(a,a.T,equal_nan=True);assert len(d['missing_chapter_ids'])==48;assert np.isnan(np.diag(a)).sum()==48;np.testing.assert_allclose(np.diag(a)[np.isfinite(np.diag(a))],1);print('All 491 chapters represented; missing data remain undefined')
